head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.onpageload = function() {
	scwin.trigger1_onclick();
	scwin.trigger2_onclick();
};

scwin.trigger1_onclick = function(e) {
	var id = "tab_" + scwin.cnt++;
	var tabOpt = {
		"id" : id + "_tabs",
		"label" : "wframe1",
		"closable" : true
	};
	var contOpt = {
		"wframe" : true,
		"scope" : true,
		"src" : "/sample/common_link/tabControl_split_WESD-873_(WSQ-4845)_WMA_wframe1.xml"
	};
	tabControl1.addTab(id, tabOpt, contOpt);
};

scwin.trigger2_onclick = function(e) {
	var id = "tab_" + scwin.cnt++;
	var tabOpt = {
		"id" : id + "_tabs",
		"label" : "wframe2",
		"closable" : true
	};
	var contOpt = {
		"wframe" : true,
		"scope" : true,
		"src" : "/sample/common_link/tabControl_split_WESD-873_(WSQ-4845)_WMA_wframe2.xml"
	};
	tabControl1.addTab(id, tabOpt, contOpt);
};

scwin.trigger3_onclick = function(e) {
	var id = "tab_" + scwin.cnt++;
	var tabOpt = {
		"id" : id + "_tabs",
		"label" : "main",
		"closable" : true
	};
	var contOpt = {
		"wframe" : true,
		"scope" : true,
		"src" : "tabControl_split_WESD-873_(WSQ-4845)_WMA_main.xml"
	};
	tabControl1.addTab(id, tabOpt, contOpt);
};

scwin.tabControl1_ontabsplit = function(tabIdx) {
	var frameObj = tabControl1.getFrame(tabIdx);
	var src = frameObj.getSrc();
	var frameId = frameObj.id;
	tabControl1.deleteTab(tabIdx);
	var options = {
		id : "popup_" + frameId,
		type : "wframePopup",
		width : "700px",
		height : "500px"
	};
	$p.openPopup(src, options);
};

scwin.checkVal = function() {
	return scwin.__getDom('popup_' + $p.id + 'tabControl1_contents_tab_2_body') != null;
};

scwin.onpageload2 = function() {
	if (typeof scwin.onpageload === "function") {
		scwin.onpageload();
	}
	if (WebSquare._xv !== "SP5") { requires("uiplugin.popup"); }
	scwin.cnt = 0;
};
